// QuiroFlow's starter catalogue of home exercises, so a clinic does not write
// every one from scratch. Each has an animated demonstration, generated by
// scripts/exercise-catalog/render.py into public/exercise-catalog/<slug>.mp4
// (with a <slug>.jpg poster) -- original drawings, ours to ship.
//
// Nothing here is in a clinic's library until someone adds it: adding copies
// the name, instructions and dose into an `exercises` row with starter_key
// set (useExerciseCatalog), so the clinic can then edit or archive its copy
// like any other, and patients see the copy. The slug is what keeps the
// video attached, and what stops the same one being added twice.
//
// Text is in both languages and taken in the language of whoever adds it,
// the same as anything else typed into the library.

export interface CatalogText {
  en: string
  es: string
}

export type CatalogRegion = 'neck' | 'shoulder' | 'back' | 'hip' | 'leg' | 'breathing'

export interface CatalogExercise {
  slug: string
  region: CatalogRegion
  name: CatalogText
  instructions: CatalogText
  sets: number | null
  reps: CatalogText
  frequency: CatalogText
}

export interface CatalogProgram {
  slug: string
  name: CatalogText
  description: CatalogText
  /** Exercise slugs, in order. */
  items: string[]
}

export const EXERCISE_CATALOG_REGIONS: { key: CatalogRegion; label: CatalogText }[] = [
  { key: 'neck', label: { en: 'Neck', es: 'Cuello' } },
  { key: 'shoulder', label: { en: 'Shoulder and upper back', es: 'Hombro y espalda alta' } },
  { key: 'back', label: { en: 'Low back and core', es: 'Zona lumbar y core' } },
  { key: 'hip', label: { en: 'Hip', es: 'Cadera' } },
  { key: 'leg', label: { en: 'Knee, ankle and balance', es: 'Rodilla, tobillo y equilibrio' } },
  { key: 'breathing', label: { en: 'Breathing and relaxation', es: 'Respiración y relajación' } },
]

const DAILY = { en: 'Daily', es: 'A diario' }
const TWICE_DAILY = { en: 'Twice a day', es: 'Dos veces al día' }
const ALT_DAYS = { en: '3 times a week', es: '3 veces por semana' }
const reps = (n: number) => ({ en: `${n}`, es: `${n}` })
const repsEach = (n: number) => ({ en: `${n} each side`, es: `${n} por lado` })
const hold = (s: number) => ({ en: `${s} s hold`, es: `${s} s` })
const holdEach = (s: number) => ({ en: `${s} s each side`, es: `${s} s por lado` })

